package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD = 1000000007

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, m, p int
	fmt.Fscan(in, &n, &m, &p)

	// Precompute factorials and inverse factorials modulo p
	fact := make([]int, n+1)
	invFact := make([]int, n+1)
	fact[0] = 1
	for i := 1; i <= n; i++ {
		fact[i] = fact[i-1] * i % p
	}
	invFact[n] = modInv(fact[n], p)
	for i := n - 1; i >= 0; i-- {
		invFact[i] = invFact[i+1] * (i+1) % p
	}

	// Precompute powers of 2 modulo p
	pow2 := make([]int, m+1)
	pow2[0] = 1
	for i := 1; i <= m; i++ {
		pow2[i] = pow2[i-1] * 2 % p
	}

	// Precompute powers of n modulo p
	pown := make([]int, m+1)
	pown[0] = 1
	for i := 1; i <= m; i++ {
		pown[i] = pown[i-1] * n % p
	}

	// Calculate the answer
	ans := 0
	for k := 0; k <= m-1; k++ {
		// C(m-1, k) * (n-k)^(m-1-k) * k * n^(m-1) * 2^m
		comb := fact[m-1] * invFact[k] % p * invFact[m-1-k] % p
		powNK := powMod(n-k, m-1-k, p)
		term := comb * powNK % p
		term = term * k % p
		term = term * pown[m-1] % p
		term = term * pow2[m] % p
		ans = (ans + term) % p
	}

	fmt.Println(ans)
}

func modInv(a, mod int) int {
	return powMod(a, mod-2, mod)
}

func powMod(a, b, mod int) int {
	res := 1
	a %= mod
	for b > 0 {
		if b&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		b >>= 1
	}
	return res
}
