const maxn = 505

var dp[maxn][maxn][maxn]int
var C[maxn][maxn]int

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, m, p int
	fmt.Fscan(in, &n, &m, &p)
	for i := 0; i <= n; i++ {
		C[i][0] = 1
		for j := 1; j <= i; j++ {
			C[i][j] = (C[i-1][j-1] + C[i-1][j]) % p
		}
	}
	for i := 0; i <= n; i++ {
		for j := 0; j <= n; j++ {
			for k := 0; k <= n; k++ {
				dp[i][j][k] = -1
			}
		}
	}
	fmt.Println(solve(n, m, p))
}

func solve(n, m, p int) int {
	return calc(n, m, p, &dp, &C)
}

func calc(n, m, p int, dp *[maxn][maxn][maxn]int, C *[maxn][maxn]int) int {
	if m == 0 {
		return 0
	}
	if n == 0 {
		return 0
	}
	if (*dp)[n][m][0] != -1 {
		return (*dp)[n][m][0]
	}
	res := 0
	for i := 1; i <= n; i++ {
		left := i - 1
		right := n - i
		for j := 0; j <= m-1; j++ {
			ways := (*C)[m-1][j]
			ways = ways * powMod(left, j, p) % p
			ways = ways * powMod(right, m-1-j, p) % p
			ways = ways * (m) % p
			res = (res + ways) % p
		}
	}
	(*dp)[n][m][0] = res
	return res
}

func powMod(a, b, mod int) int {
	res := 1
	for b > 0 {
		if b&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		b >>= 1
	}
	return res
}
