package main

import (
	"bufio"
	"fmt"
	"os"
)

const MAXN = 505

var n, m, MOD int
var dp[MAXN][MAXN][2][2]int
var C[MAXN][MAXN]int

func main() {
	in := bufio.NewReader(os.Stdin)
	fmt.Fscan(in, &n, &m, &MOD)

	// Precompute combinations
	for i := 0; i <= n; i++ {
		C[i][0] = 1
		for j := 1; j <= i; j++ {
			C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD
		}
	}

	// Initialize DP
	for i := 0; i <= n; i++ {
		for j := 0; j <= m; j++ {
			for k := 0; k < 2; k++ {
				for l := 0; l < 2; l++ {
					dp[i][j][k][l] = -1
				}
			}
		}
	}

	// Base case
	dp[0][0][0][0] = 0
	dp[0][0][0][1] = 0
	dp[0][0][1][0] = 0
	dp[0][0][1][1] = 0

	// Fill DP table
	for i := 0; i <= n; i++ {
		for j := 0; j <= m; j++ {
			for k := 0; k < 2; k++ {
				for l := 0; l < 2; l++ {
					if dp[i][j][k][l] == -1 {
						continue
					}
					cur := dp[i][j][k][l]
					// Try placing next person
					if j < m {
						// Person enters from left
						nk := k
						if i == 0 {
							nk = 1
						}
						if i+1 <= n {
							nxt := cur
							if nk == 1 {
								nxt = (nxt + i) % MOD
							}
							if dp[i+1][j+1][nk][l] == -1 || dp[i+1][j+1][nk][l] > nxt {
								dp[i+1][j+1][nk][l] = nxt
							}
						}
						// Person enters from right
						nl := l
						if i == 0 {
							nl = 1
						}
						if i+1 <= n {
							nxt := cur
							if nl == 1 {
								nxt = (nxt + i) % MOD
							}
							if dp[i+1][j+1][k][nl] == -1 || dp[i+1][j+1][k][nl] > nxt {
								dp[i+1][j+1][k][nl] = nxt
							}
						}
					}
					// Skip this position
					if i+1 <= n {
						if dp[i+1][j][k][l] == -1 || dp[i+1][j][k][l] > cur {
							dp[i+1][j][k][l] = cur
						}
					}
				}
			}
		}
	}

	// Calculate answer
	ans := 0
	for k := 0; k < 2; k++ {
		for l := 0; l < 2; l++ {
			if dp[n][m][k][l] != -1 {
				ans = (ans + dp[n][m][k][l]) % MOD
			}
		}
	}

	// Multiply by n^m * 2^m
	powNM := 1
	for i := 0; i < m; i++ {
		powNM = (powNM * n) % MOD
	}
	pow2M := 1
	for i := 0; i < m; i++ {
		pow2M = (pow2M * 2) % MOD
	}
	ans = (ans * powNM) % MOD
	ans = (ans * pow2M) % MOD

	fmt.Println(ans)
}
