package main

import (
	"bufio"
	"fmt"
	"os"
)

const maxn = 505

var n, m, mod int
var dp[maxn][maxn][2]int
var C[maxn][maxn]int

func main() {
	in := bufio.NewReader(os.Stdin)
	fmt.Fscan(in, &n, &m, &mod)
	for i := 0; i <= n; i++ {
		C[i][0] = 1
		for j := 1; j <= i; j++ {
			C[i][j] = (C[i-1][j] + C[i-1][j-1]) % mod
		}
	}
	for i := 0; i <= n; i++ {
		for j := 0; j <= m; j++ {
			dp[i][j][0] = 0
			dp[i][j][1] = 0
		}
	}
	dp[0][0][0] = 1
	for i := 0; i < n; i++ {
		for j := 0; j <= m; j++ {
			if dp[i][j][0] == 0 && dp[i][j][1] == 0 {
				continue
			}
			// Place a person entering from the left
			for k := 1; k <= m-j; k++ {
				ways := C[m-j][k] * dp[i][j][0] % mod
				ways = ways * powMod(k, mod-2, mod) % mod
				dp[i+1][j+k][0] = (dp[i+1][j+k][0] + ways) % mod
			}
			// Place a person entering from the right
			for k := 1; k <= m-j; k++ {
				ways := C[m-j][k] * dp[i][j][1] % mod
				ways = ways * powMod(k, mod-2, mod) % mod
				dp[i+1][j+k][1] = (dp[i+1][j+k][1] + ways) % mod
			}
			// Switch direction
			dp[i+1][j][1] = (dp[i+1][j][1] + dp[i][j][0]) % mod
			dp[i+1][j][0] = (dp[i+1][j][0] + dp[i][j][1]) % mod
		}
	}
	ans := 0
	for i := 1; i <= n; i++ {
		for j := 0; j <= m; j++ {
			ans = (ans + dp[i][j][0]) % mod
			ans = (ans + dp[i][j][1]) % mod
		}
	}
	fmt.Println(ans)
}

func powMod(a, b, mod int) int {
	res := 1
	for b > 0 {
		if b&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		b >>= 1
	}
	return res
}
