package main

import (
	"bufio"
	"fmt"
	"os"
)

const maxn = 505

var n, m, mod int
var C[maxn][maxn]int
var f[maxn][maxn]int

func main() {
	in := bufio.NewReader(os.Stdin)
	fmt.Fscan(in, &n, &m, &mod)
	for i := 0; i <= n; i++ {
		C[i][0] = 1
		for j := 1; j <= i; j++ {
			C[i][j] = (C[i-1][j-1] + C[i-1][j]) % mod
		}
	}
	for i := 1; i <= n; i++ {
		f[i][0] = 1
	}
	for i := 1; i <= n; i++ {
		for j := 1; j <= m; j++ {
			f[i][j] = (f[i-1][j] + f[i-1][j-1]*i) % mod
		}
	}
	ans := 0
	for k := 1; k <= m; k++ {
		for i := 1; i <= n; i++ {
			for j := 1; j <= n-i+1; j++ {
				tmp := C[n-i][k-1] * f[j][k-1] % mod
				tmp = tmp * f[n-i-j+1][m-k] % mod
				tmp = tmp * (j - 1) % mod
				tmp = tmp * C[m-1][k-1] % mod
				ans = (ans + tmp) % mod
			}
		}
	}
	fmt.Println(ans)
}
