var dp [maxn][maxn]int

func main() {
	in := bufio.NewReader(os.Stdin)
	fmt.Fscan(in, &n, &m, &p)
	for i := 0; i <= n; i++ {
		C[i][0] = 1
		for j := 1; j <= i; j++ {
			C[i][j] = (C[i-1][j-1] + C[i-1][j]) % p
		}
	}
	for i := 0; i <= n; i++ {
		dp[i][0] = 1
	}
	for i := 1; i <= n; i++ {
		for j := 1; j <= m; j++ {
			dp[i][j] = dp[i-1][j]
			if j <= i {
				dp[i][j] = (dp[i][j] + dp[i-1][j-1]) % p
			}
		}
	}
	ans := 0
	for k := 1; k <= m; k++ {
		ways := C[m][k]
		ways = ways * dp[n][k] % p
		ways = ways * dp[n][k] % p
		ways = ways * C[m][k] % p
		ways = ways * k % p
		ways = ways * k % p
		ans = (ans + ways) % p
	}
	fmt.Println(ans)
}
