```go
package main

import (
	"bufio"
	"fmt"
	"os"
)

const (
	MAXN = 505
	MAXM = 505
)

var (
	n, m, p int
	dp [MAXN][MAXM][MAXN][2]int
)

func main() {
	in := bufio.NewReader(os.Stdin)
	fmt.Fscan(in, &n, &m, &p)

	// Initialize DP table
	for i := 0; i <= n+1; i++ {
		for j := 0; j <= m; j++ {
			for k := 0; k <= n+1; k++ {
				dp[i][j][k][0] = 0
				dp[i][j][k][1] = 0
			}
		}
	}

	// Base case: after 0 participants, all computers are available
	for i := 1; i <= n; i++ {
		dp[i][0][i][0] = 1
		dp[i][0][i][1] = 1
	}

	// Fill DP table
	for j := 1; j <= m; j++ {
		for i := 1; i <= n; i++ {
			for k := 1; k <= n; k++ {
				// Participant enters from left (L)
				// If the current computer is the first available from the left
				if k == i {
					dp[i][j][k][0] = (dp[i][j][k][0] + dp[i-1][j-1][k][0]) % p
					dp[i][j][k][0] = (dp[i][j][k][0] + dp[i-1][j-1][k][1]) % p
				} else {
					dp[i][j][k][0] = (dp[i][j][k][0] + dp[i-1][j][k][0]) % p
					dp[i][j][k][0] = (dp[i][j][k][0] + dp[i-1][j][k][1]) % p
				}

				// Participant enters from right (R)
				// If the current computer is the first available from the right
				if k == i {
					dp[i][j][k][1] = (dp[i][j][k][1] + dp[i][j-1][k][0]) % p
					dp[i][j][k][1] = (dp[i][j][k][1] + dp[i][j-1][k][1]) % p
				} else {
					dp[i][j][k][1] = (dp[i][j][k][1] + dp[i+1][j][k][0]) % p
					dp[i][j][k][1] = (dp[i][j][k][1] + dp[i+1][j][k][1]) % p
				}
			}
		}
	}

	// Calculate the final answer
	ans := 0
	for i := 1; i <= n; i++ {
		for k := 1; k <= n; k++ {
			ans = (ans + dp[i][m][k][0]) % p
			ans = (ans + dp[i][m][k][1]) % p
		}
	}

	fmt.Println(ans)
}
